function buildLines(words, o) {
    var fd = o.fd, e = 1e-6, ml = o.maxLines || 1, subs = [], lines = [], cur = [], len = 0, i, w, n, S, k;
    function endLine() { if (cur.length) lines.push(cur); cur = []; len = 0; }
    function endSub() { endLine(); if (lines.length) subs.push({ lines: lines }); lines = []; }
    function nextLine() { endLine(); if (lines.length >= ml) endSub(); }
    for (i = 0; i < words.length; i++) {
        w = words[i];
        if (cur.length && !w.lk && o.maxChars > 0 && len + 1 + w.text.length > o.maxChars) nextLine();
        len += (cur.length ? 1 : 0) + w.text.length; cur.push(w);
        n = words[i + 1];
        if (w.br === true) endSub();
        else if (w.br === 'line') { if (w.lk) endLine(); else nextLine(); }
        else if (w.br !== false && !w.lk) {
            if (/[.?!]$/.test(w.text) || (n && n.start - w.end > o.pauseBreak)) endSub();
            else if (cur.length >= o.wordsPerLine) nextLine();
        }
    }
    endSub();
    for (i = 0; i < subs.length; i++) {
        S = subs[i]; S.words = []; k = [];
        S.lines.forEach(function (L) { S.words = S.words.concat(L); k.push(L.map(function (x) { return x.text; }).join(' ')); });
        S.text = k.join('\r');
        S.lk = !!S.words[0].lk;
        S.start = Math.floor(S.words[0].start / fd + e) * fd;
        S.end = Math.max(Math.ceil(S.words[S.words.length - 1].end / fd - e) * fd, S.start + (S.lk ? 1 : o.minFrames) * fd);
    }
    for (i = 0; i < subs.length - 1; i++) {
        n = subs[i + 1].start;
        if ((!subs[i].lk && n - subs[i].end < o.closeGapFrames * fd - e) || subs[i].end > n) subs[i].end = n;
    }
    return subs;
}
